const telegram = $input.first().json.telegram
const text = telegram.message.text

const regexMap = [
  { 
    type: 'ING_BUY', // Increase stock + Weighted Average Cost
    re: /^(?:bought|add)\s+(?<quantity>\d+(\.\d+)?)\s*(?<unit>\w+)?\s*(?<name>.+?)\s+for\s+(?:[€$£]\s*)?(?<cost>\d+(\.\d+)?)$/i 
  },
  { 
    type: 'ING_USAGE', // Decrease stock quantity
    re: /^(?:used|decrease|consume)\s+(?<quantity>\d+(\.\d+)?)\s*(?<unit>\w+)?\s*(?:of\s+)?(?<name>.+?)$/i 
  },
  { 
    type: 'ING_PRICE', // Update cost only
    re: /^(?<name>.+?)\s+(?:price|cost)\s+(?:is\s+now|to)\s+(?:[€$£]\s*)?(?<cost>\d+(\.\d+)?)$/i 
  },
  { 
    type: 'ING_DELETE', // Permanent removal from DB
    re: /^(?:delete|remove\s+ingredient|wipe)\s+(?<name>.+?)$/i 
  },
  { 
    type: 'ING_STATUS', // Single item report
    re: /^(?:status|stock|info)\s+(?:of|for|on)\s+(?<name>.+?)$/i 
  },
  { 
    type: 'ING_LIST', // Full inventory list
    re: /^(?:list|show)\s+(?:all\s+)?(?:ingredients|inventory|stock)$/i 
  }
];

let result = { sub_match_type: 'NO_MATCH', data: {}, telegram:telegram };

for (const item of regexMap) {
  const match = text.match(item.re);
  if (match) {
    result.sub_match_type = item.type;
